import 'package:flutter/material.dart';import '../widgets/ui.dart';import '../models/roles.dart';import '../data/sai_repository.dart';import '../core/theme.dart';
class DashboardScreen extends StatelessWidget{const DashboardScreen({super.key,required this.roles,required this.repo,required this.open});final Set<AppRole> roles;final SaiRepository repo;final void Function(Feature) open;
@override Widget build(BuildContext context){final allowed=allowedFeatures(roles);final items=<({Feature feature,String title,IconData icon})>[(feature:Feature.classes,title:'الصفوف',icon:Icons.meeting_room_outlined),(feature:Feature.courses,title:'المقررات',icon:Icons.menu_book_outlined),(feature:Feature.learning,title:'تعلم الصينية',icon:Icons.translate),(feature:Feature.student,title:'الطلاب',icon:Icons.people_outline),(feature:Feature.finance,title:'الرسوم',icon:Icons.payments_outlined),(feature:Feature.attendance,title:'الحضور',icon:Icons.fact_check_outlined),(feature:Feature.content,title:'المحتوى',icon:Icons.edit_note),(feature:Feature.library,title:'المكتبة',icon:Icons.local_library_outlined)];return ListView(padding:const EdgeInsets.all(18),children:[const SaiHeader(title:'مرحباً بك في كلية ساي',subtitle:'لوحتك الأكاديمية والإدارية'),const SaiSection(title:'نظرة عامة'),FutureBuilder<List<Map<String,dynamic>>>(future:repo.classes(),builder:(context,s)=>Row(children:[Expanded(child:SaiMetric(value:s.hasData?'${s.data!.length}':'—',label:'الصفوف المتاحة',icon:Icons.school_outlined)),const SizedBox(width:10),Expanded(child:SaiMetric(value:'${roles.length}',label:'الأدوار المعتمدة',icon:Icons.verified_user_outlined))])),const SaiSection(title:'الوصول السريع'),LayoutBuilder(builder:(context,c)=>GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:c.maxWidth>650?4:2,childAspectRatio:c.maxWidth>650?2.1:1.55,crossAxisSpacing:10,mainAxisSpacing:10),itemCount:items.where((e)=>allowed.contains(e.feature)).length,itemBuilder:(context,i){final item=items.where((e)=>allowed.contains(e.feature)).toList()[i];return Card(child:InkWell(onTap:()=>open(item.feature),borderRadius:BorderRadius.circular(18),child:Padding(padding:const EdgeInsets.all(15),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Icon(item.icon,color